const statuses: { id: OrderStatus; name: string; icon: string }[] = [{ id: 'pendiente_entrega', name: 'Pendiente', icon: 'clock-outline' }, { id: 'entregado', name: 'Entregado', icon: 'check-circle-outline' }, { id: 'cancelado', name: 'Cancelado', icon: 'close-circle-outline' }];
const payments: { id: PaymentMethod; name: string; icon: string }[] = [{ id: 'transferencia', name: 'Transferencia', icon: 'bank-transfer' }, { id: 'efectivo', name: 'Efectivo', icon: 'cash' }, { id: 'gratis', name: 'Gratis', icon: 'gift-outline' }, { id: 'desconocido', name: 'Sin definir', icon: 'help-circle-outline' }];
