type CountDayProps = { date?: DateData; state?: string; selected: string; counts: Counts; locations: Location[]; onSelect: (date: string) => void };
function CountDay({ date, state, selected, counts, locations, onSelect }: CountDayProps) {
  if (!date) return <View style={{ minHeight: 64 }} />;
  const entries = Object.entries(counts[date.dateString] ?? {});
  const isSelected = date.dateString === selected;
  const isToday = date.dateString === dateNow();
  const description = entries.map(([id, count]) => `${locations.find(location => location.id === id)?.name ?? id}: ${count}`).join(', ');
  return <TouchableOpacity accessibilityRole="button" accessibilityState={{ selected: isSelected }} accessibilityLabel={`${dateLabel(date.dateString)}. ${description || 'Sin pedidos'}`} onPress={() => onSelect(date.dateString)} style={{ minHeight: 64, width: '100%', alignItems: 'center', paddingVertical: 5, borderRadius: 12, borderWidth: isToday ? 3 : isSelected ? 1 : 0, borderColor: isToday ? COLORS.accent : COLORS.primary, backgroundColor: isToday ? COLORS.primary : isSelected ? COLORS.orangeSoft : 'transparent' }}>
    <Text style={{ fontSize: 14, color: state === 'disabled' ? COLORS.disabled : palette.ink, fontWeight: state === 'today' || isSelected ? '700' : '400' }}>{date.day}{isToday ? '\nHOY' : ''}</Text>
    <View style={{ flexDirection: 'row', flexWrap: 'wrap', justifyContent: 'center', gap: 2, marginTop: 4 }}>{entries.map(([id, count]) => <View key={id} style={{ minWidth: 11, paddingHorizontal: 2, borderRadius: 3, backgroundColor: `${locations.find(location => location.id === id)?.color ?? palette.accent}12` }}><Text style={{ fontSize: 10, lineHeight: 14, fontWeight: '800', textAlign: 'center', color: locations.find(location => location.id === id)?.color ?? palette.accent }}>{count}</Text></View>)}</View>
  </TouchableOpacity>;
}
function PickupCalendar({ month, day, counts, locations, onDay, onMonth, mode, onMode }: { month: string; day: string; counts: Counts; locations: Location[]; onDay: (day: string) => void; onMonth: (month: string) => void; mode: CalendarView; onMode: (mode: CalendarView) => void }) {
  const renderDay = useCallback((props: { date?: DateData; state?: string }) => <CountDay {...props} selected={day} counts={counts} locations={locations} onSelect={onDay} />, [day, counts, locations, onDay]);
  return <Panel><Text variant="titleMedium">Calendario de retiros y ventas</Text><View style={styles.wrap}>{([{ id: 'day', name: 'Día' }, { id: 'week', name: 'Semana' }, { id: 'month', name: 'Mes' }] as const).map(view => <Chip key={view.id} selected={mode === view.id} onPress={() => onMode(view.id)}>{view.name}</Chip>)}</View><View style={[styles.row, { justifyContent: 'space-between' }]}><IconButton icon="chevron-left" accessibilityLabel="Período anterior" onPress={() => onDay(shiftCalendarDate(mode === 'month' ? `${month}-01` : day, -1, mode))} /><Button onPress={() => onDay(dateNow())}>Hoy</Button><IconButton icon="chevron-right" accessibilityLabel="Período siguiente" onPress={() => onDay(shiftCalendarDate(mode === 'month' ? `${month}-01` : day, 1, mode))} /></View>{mode === 'month' ? <Calendar firstDay={1} key={month} current={`${month}-01`} dayComponent={renderDay} onMonthChange={value => onMonth(value.dateString.slice(0, 7))} theme={calendarTheme} enableSwipeMonths /> : mode === 'week' ? <View style={styles.wrap}>{calendarWeek(day).map(date => <TouchableOpacity key={date} accessibilityRole="button" accessibilityState={{ selected: date === day }} onPress={() => onDay(date)} style={{ width: '30%', minHeight: 80, padding: 8, borderRadius: 12, borderWidth: date === dateNow() ? 3 : date === day ? 2 : 1, borderColor: date === dateNow() ? COLORS.accent : date === day ? COLORS.primary : COLORS.border, backgroundColor: date === dateNow() ? COLORS.orangeSoft : 'transparent' }}><Text style={{ fontWeight: '700' }}>{new Date(`${date}T12:00:00`).toLocaleDateString('es-AR', { weekday: 'short', day: 'numeric', month: 'short' })}</Text>{Object.entries(counts[date] ?? {}).map(([id, count]) => <Text key={id} style={{ color: locations.find(location => location.id === id)?.color }}>{locations.find(location => location.id === id)?.name}: {count}</Text>)}</TouchableOpacity>)}</View> : <Text variant="titleLarge">{dateLabel(day)}</Text>}<View style={styles.wrap}>{locations.map(location => <View key={location.id} style={[styles.row, { gap: 5 }]}><View style={{ width: 7, height: 7, borderRadius: 4, backgroundColor: location.color }} /><Text style={{ fontSize: 11, color: palette.muted }}>{location.name}</Text></View>)}</View><Text style={{ fontSize: 12, lineHeight: 18, color: palette.muted }}>Los números indican pedidos pendientes de retiro. Los entregados siguen visibles en el detalle.</Text></Panel>;
}

