    setDraft({ ...draft, location_id: lastOrder.location_id, locationManuallySet: true, append_order_id: undefined, lines: lastOrder.lines.map(line => ({ product_id: line.product_id, quantity: saleQuantity(line.quantity), is_gift: false })) });
